export const DEFAULT_PORTS = {
  http: '80',
  https: '443',
  ws: '80',
  wss: '443',
  ftp: '21',
}

/** Raised when a component holds a `%` not followed by two hex digits. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Raised when a `resolve` base writes no scheme. */
export class BaseHasNoSchemeError extends Error {
  constructor() {
    super('the base has no scheme')
  }
}

function isUnreservedChar(ch) {
  return /[A-Za-z0-9\-._~]/.test(ch)
}

/**
 * Validates the percent-encoding triplets in `value`, throwing
 * `TruncatedPercentEncodingError(component)` on the first malformed one.
 */
function checkPercentEncoding(value, component) {
  for (let i = 0; i < value.length; i++) {
    if (value[i] === '%') {
      const hex = value.slice(i + 1, i + 3)
      if (hex.length < 2 || !/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new TruncatedPercentEncodingError(component)
      }
      i += 2
    }
  }
