 * Uppercases the hex digits of every `%XX` triplet in `value`, replacing it
 * with the literal character when that character is unreserved. Assumes
 * `checkPercentEncoding` has already validated `value`.
 */
function normalizePercentEncoding(value) {
  let result = ''
  for (let i = 0; i < value.length; i++) {
    const ch = value[i]
