      const hex = value.slice(i + 1, i + 3).toUpperCase()
      const decoded = String.fromCharCode(parseInt(hex, 16))
      result += isUnreservedChar(decoded) ? decoded : '%' + hex
      i += 2
    } else {
      result += ch
    }
