    scheme = rest.slice(0, specialIndex)
    rest = rest.slice(specialIndex + 1)
  }

  let authorityParts = null
  if (rest.startsWith('//')) {
    let end = rest.length
    for (let i = 2; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authorityParts = parseAuthority(rest.slice(2, end))
    rest = rest.slice(end)
  }

  const hashIndex = rest.indexOf('#')
  const fragment = hashIndex === -1 ? null : rest.slice(hashIndex + 1)
  const beforeFragment = hashIndex === -1 ? rest : rest.slice(0, hashIndex)

  const questionIndex = beforeFragment.indexOf('?')
  const path = questionIndex === -1 ? beforeFragment : beforeFragment.slice(0, questionIndex)
  const query = questionIndex === -1 ? null : beforeFragment.slice(questionIndex + 1)

  return { scheme, authorityParts, path, query, fragment }
