  let out = ''
  if (parsed.scheme !== null) out += parsed.scheme + ':'
  if (parsed.authorityParts !== null) {
    out += '//'
    const { userinfo, host, port } = parsed.authorityParts
    if (userinfo !== null) out += userinfo + '@'
    out += host
    if (port !== null) out += ':' + port
