 * Resolves `refStr` against `baseStr` per RFC 3986 section 5.2.2 (strict),
 * then normalizes the result. Throws `BaseHasNoSchemeError` when the base
 * writes no scheme.
 */
export function resolve(baseStr, refStr) {
  const base = parseUri(baseStr)
  if (base.scheme === null) throw new BaseHasNoSchemeError()
  const ref = parseUri(refStr)

  const target = {}
  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    target.authorityParts = ref.authorityParts
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.authorityParts !== null) {
    target.scheme = base.scheme
    target.authorityParts = ref.authorityParts
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.path === '') {
    target.scheme = base.scheme
    target.authorityParts = base.authorityParts
    target.path = base.path
    target.query = ref.query !== null ? ref.query : base.query
